using System;using System.Collections.Generic;using System.Linq;using System.Globalization;using Avalonia;using Avalonia.Controls;using Avalonia.Layout;using Avalonia.Media;using Avalonia.Interactivity;using Kreta.Core;using Kreta.Contexts;public class SzabalyzatKezeloView : IEvolView{    private IDirectorContext? _context;    private ListBox? _regulationListBox;    private TextBox? _titleTextBox;    private TextBox? _versionTextBox;    private TextBox? _contentTextBox;    private DatePicker? _effectiveDatePicker;    private TextBlock? _statusTextBlock;    private Button? _saveButton;    private Button? _deleteButton;    private Button? _newButton;    private StackPanel? _editPanel;    private List<GenericRecord>? _regulations;    private GenericRecord? _selectedRegulation;    private const string EntityType = "SchoolRegulation";    public new string Name => "Szabályzat Kezelő";    public string Description => "Iskolai szabályzatok létrehozása, szerkesztése és törlése, verziószámmal ellátva.";    public SzabalyzatKezeloView() { }    public SzabalyzatKezeloView(IDirectorContext context)    {        _context = context;    }    public Control CreateView()    {        var mainGrid = new Grid        {            ColumnDefinitions = new ColumnDefinitions("1*,2*"),            Margin = new Thickness(10)        };        var leftPanel = new StackPanel { Spacing = 10 };        leftPanel.Children.Add(new TextBlock { Text = "Szabályzatok", FontSize = 18, FontWeight = FontWeight.Bold });        _regulationListBox = new ListBox { Height = 400 };        _regulationListBox.SelectionChanged += RegulationListBox_SelectionChanged;        leftPanel.Children.Add(_regulationListBox);        _newButton = new Button { Content = "Új Szabályzat" };        _newButton.Click += NewButton_Click;        leftPanel.Children.Add(_newButton);        Grid.SetColumn(leftPanel, 0);        mainGrid.Children.Add(leftPanel);        _editPanel = new StackPanel        {            Spacing = 10,            IsEnabled = false,            Margin = new Thickness(20, 0, 0, 0)        };        _editPanel.Children.Add(new TextBlock { Text = "Szerkesztés", FontSize = 18, FontWeight = FontWeight.Bold });        _editPanel.Children.Add(new TextBlock { Text = "Cím:" });        _titleTextBox = new TextBox();        _editPanel.Children.Add(_titleTextBox);        _editPanel.Children.Add(new TextBlock { Text = "Verziószám:" });        _versionTextBox = new TextBox();        _editPanel.Children.Add(_versionTextBox);        _editPanel.Children.Add(new TextBlock { Text = "Hatályba lépés dátuma:" });        _effectiveDatePicker = new DatePicker();        _editPanel.Children.Add(_effectiveDatePicker);        _editPanel.Children.Add(new TextBlock { Text = "Tartalom:" });        _contentTextBox = new TextBox        {            AcceptsReturn = true,            TextWrapping = TextWrapping.Wrap,            MinHeight = 150        };        _editPanel.Children.Add(_contentTextBox);        var buttonPanel = new StackPanel { Orientation = Orientation.Horizontal, Spacing = 10 };        _saveButton = new Button { Content = "Mentés" };        _saveButton.Click += SaveButton_Click;        buttonPanel.Children.Add(_saveButton);        _deleteButton = new Button { Content = "Törlés", IsEnabled = false };        _deleteButton.Click += DeleteButton_Click;        buttonPanel.Children.Add(_deleteButton);        _editPanel.Children.Add(buttonPanel);        _statusTextBlock = new TextBlock { Margin = new Thickness(0, 10, 0, 0) };        _editPanel.Children.Add(_statusTextBlock);        Grid.SetColumn(_editPanel, 1);        mainGrid.Children.Add(_editPanel);        LoadRegulations();        return mainGrid;    }    private void LoadRegulations()    {        if (_context == null || _regulationListBox == null) return;        try        {            _regulations = _context.QueryEntities(EntityType);            _regulationListBox.ItemsSource = _regulations.Select(r => r.Data.GetValueOrDefault("Title", "Névtelen") + " (v" + r.Data.GetValueOrDefault("Version", "?") + ")").ToList();        }        catch (Exception ex)        {            SetStatus($"Hiba a szabályzatok betöltése közben: {ex.Message}", true);        }    }    private void RegulationListBox_SelectionChanged(object? sender, SelectionChangedEventArgs e)    {        if (_regulationListBox == null || _regulationListBox.SelectedIndex < 0 || _regulations == null) return;        _selectedRegulation = _regulations[_regulationListBox.SelectedIndex];        if (_selectedRegulation != null && _titleTextBox != null && _versionTextBox != null && _contentTextBox != null && _effectiveDatePicker != null && _editPanel != null && _deleteButton != null)        {            _titleTextBox.Text = _selectedRegulation.Data.GetValueOrDefault("Title", "");            _versionTextBox.Text = _selectedRegulation.Data.GetValueOrDefault("Version", "");            _contentTextBox.Text = _selectedRegulation.Data.GetValueOrDefault("Content", "");            if (DateTime.TryParse(_selectedRegulation.Data.GetValueOrDefault("EffectiveDate", ""), CultureInfo.InvariantCulture, out var date))            {                _effectiveDatePicker.SelectedDate = date;            }            else            {                _effectiveDatePicker.SelectedDate = null;            }            _editPanel.IsEnabled = true;            _deleteButton.IsEnabled = true;        }    }    private void ClearForm()    {        _selectedRegulation = null;        if (_regulationListBox != null) _regulationListBox.SelectedIndex = -1;        if (_titleTextBox != null) _titleTextBox.Text = string.Empty;        if (_versionTextBox != null) _versionTextBox.Text = string.Empty;        if (_contentTextBox != null) _contentTextBox.Text = string.Empty;        if (_effectiveDatePicker != null) _effectiveDatePicker.SelectedDate = DateTime.Today;        if (_deleteButton != null) _deleteButton.IsEnabled = false;        if (_editPanel != null) _editPanel.IsEnabled = true;    }        private void NewButton_Click(object? sender, RoutedEventArgs e)    {        ClearForm();        SetStatus("Új szabályzat felvétele. Adja meg az adatokat.", false);    }    private void DeleteButton_Click(object? sender, RoutedEventArgs e)    {        if (_context == null || _selectedRegulation == null) return;        try        {            _context.DeleteEntity(EntityType, _selectedRegulation.Id);            SetStatus("Szabályzat sikeresen törölve.", false);            LoadRegulations();            ClearForm();            if (_editPanel != null) _editPanel.IsEnabled = false;        }        catch (Exception ex)        {            SetStatus($"Hiba a törlés során: {ex.Message}", true);        }    }    private void SaveButton_Click(object? sender, RoutedEventArgs e)    {        if (_context == null || _titleTextBox == null || _versionTextBox == null || _contentTextBox == null || _effectiveDatePicker == null) return;        if (string.IsNullOrWhiteSpace(_titleTextBox.Text) || string.IsNullOrWhiteSpace(_versionTextBox.Text))        {            SetStatus("A cím és a verziószám megadása kötelező!", true);            return;        }        try        {            var data = new Dictionary<string, string>            {                { "Title", _titleTextBox.Text },                { "Version", _versionTextBox.Text },                { "Content", _contentTextBox.Text ?? string.Empty },                { "EffectiveDate", _effectiveDatePicker.SelectedDate?.ToString("o", CultureInfo.InvariantCulture) ?? string.Empty }            };            int idToSave = _selectedRegulation?.Id ?? 0;            _context.SaveEntity(EntityType, data, idToSave == 0 ? null : (int?)idToSave);            SetStatus("Szabályzat sikeresen mentve.", false);            LoadRegulations();            ClearForm();            if (_editPanel != null) _editPanel.IsEnabled = false;        }        catch (Exception ex)        {            SetStatus($"Hiba a mentés során: {ex.Message}", true);        }    }    private void SetStatus(string message, bool isError)    {        if (_statusTextBlock == null) return;        _statusTextBlock.Text = message;        _statusTextBlock.Foreground = isError ? Brushes.Red : Brushes.Green;    }}